const upsertImportedContacts = `-- name: UpsertImportedContacts :many
INSERT INTO contacts (id, workspace_id, name, phone, email, opt_in, opt_in_source, opt_in_at, source, attributes)
SELECT u.id, $1, u.name, u.phone, NULLIF(u.email, '')::citext, 'in', 'import', now(), 'import',
       u.attributes::jsonb
FROM (SELECT unnest($2::uuid[]) AS id, unnest($3::text[]) AS name, unnest($4::text[]) AS phone,
             unnest($5::text[]) AS email, unnest($6::text[]) AS attributes) AS u
ON CONFLICT (workspace_id, phone) DO UPDATE
SET name          = CASE WHEN EXCLUDED.name <> '' THEN EXCLUDED.name ELSE contacts.name END,
    email         = COALESCE(EXCLUDED.email, contacts.email),
    attributes    = contacts.attributes || EXCLUDED.attributes,
    opt_in        = CASE WHEN contacts.opt_in = 'pending' THEN 'in' ELSE contacts.opt_in END,
    opt_in_source = CASE WHEN contacts.opt_in = 'pending' THEN 'import' ELSE contacts.opt_in_source END,
    opt_in_at     = CASE WHEN contacts.opt_in = 'pending' THEN now() ELSE contacts.opt_in_at END
RETURNING id, phone, (xmax = 0)::boolean AS inserted
`

type UpsertImportedContactsParams struct {
	WorkspaceID uuid.UUID
	Ids         []uuid.UUID
	Names       []string
	Phones      []string
	Emails      []string
	Attributes  []string
}

type UpsertImportedContactsRow struct {
	ID       uuid.UUID
	Phone    string
	Inserted bool
}

// One import batch. A new contact is opted in from the import; an existing one keeps its values
// except the non-empty imported ones, and an opt-out stays out (an import never re-subscribes).
func (q *Queries) UpsertImportedContacts(ctx context.Context, arg UpsertImportedContactsParams) ([]UpsertImportedContactsRow, error) {
	rows, err := q.db.Query(ctx, upsertImportedContacts,
		arg.WorkspaceID,
		arg.Ids,
		arg.Names,
		arg.Phones,
		arg.Emails,
		arg.Attributes,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UpsertImportedContactsRow{}
	for rows.Next() {
		var i UpsertImportedContactsRow
		if err := rows.Scan(&i.ID, &i.Phone, &i.Inserted); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
